export function confirmedProductTweet({ id, text, raw, product, chatId, message, html }) {
  if (typeof id !== "string" || !id || typeof text !== "string" || !raw || typeof raw !== "object")
    throw new Error("The X post was not confirmed; inspect X before replaying.");
  return { product, chatId, message, html, tweet: { id, text, raw } };
}
export function confirmedProductTelegram({ output, product, tweet }) {
  if (
    !output ||
    typeof output !== "object" ||
    !Number.isSafeInteger(output.messageId) ||
    output.messageId <= 0 ||
    !output.chat ||
    !Number.isSafeInteger(output.chat.id)
  )
    throw new Error(
      "The Telegram post was not confirmed; inspect both destinations before replaying.",
    );
  return { product, tweet, telegram: output };
}

export default function (input) {
  return confirmedProductTweet(input);
}

